INSERT INTO public.animais (name, age, type, gender, "desc", img, tag, status) VALUES
('Thor', '2 anos', 'cachorro', 'macho', 'Brincalhão, cheio de energia e ama crianças. Thor espera por alguém que acompanhe sua animação.', 'https://images.unsplash.com/photo-1651212508936-dfb6f6ea3d81?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxnb2xkZW4lMjByZXRyaWV2ZXIlMjBwdXBweSUyMGhhcHB5fGVufDF8fHx8MTc3MjYyMzExOXww&ixlib=rb-4.1.0&q=80&w=1080', 'Destaque', 'disponível'),
('Luna', '3 anos', 'gato', 'fêmea', 'Serena e independente, Luna adora uma boa sessão de carinho no fim do dia.', 'https://images.unsplash.com/photo-1769634847861-69ee4fa8c343?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxjYXQlMjBhZG9wdGlvbiUyMHNoZWx0ZXIlMjBjdXRlJTIwa2l0dGVufGVufDF8fHx8MTc3MjY0NzY2MHww&ixlib=rb-4.1.0&q=80&w=1080', 'Nova', 'disponível'),
('Zeus', '4 anos', 'cachorro', 'macho', 'Tranquilo, leal e muito carinhoso. Zeus é perfeito para quem busca um companheiro fiel.', 'https://images.unsplash.com/photo-1671572418326-69416b142404?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxibGFjayUyMGRvZyUyMHJlc2N1ZSUyMHBvcnRyYWl0JTIwY2xvc2UlMjB1cHxlbnwxfHx8fDE3NzI2NDc2NjF8MA&ixlib=rb-4.1.0&q=80&w=1080', NULL, 'disponível'),
('Mel', '1 ano', 'cachorro', 'fêmea', 'Doce como o nome, Mel está pronta para trazer alegria para qualquer lar que a receba.', 'https://images.unsplash.com/photo-1762893620918-af52d50a7dde?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxtaXhlZCUyMGJyZWVkJTIwZG9nJTIwcGxheWZ1bCUyMG91dGRvb3J8ZW58MXx8fHwxNzcyNjQ3NjY1fDA&ixlib=rb-4.1.0&q=80&w=1080', 'Urgente', 'disponível'),
('Nala', '5 anos', 'gato', 'fêmea', 'Elegante e curiosa, Nala observa tudo com seus olhos de amêndoa. Adora janelas.', 'https://images.unsplash.com/photo-1708417250704-770feaf07660?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxncmV5JTIwY2F0JTIwc3dlZXQlMjBsb29raW5nfGVufDF8fHx8MTc3MjY0NzY2M3ww&ixlib=rb-4.1.0&q=80&w=1080', NULL, 'disponível'),
('Simba', '2 anos', 'gato', 'macho', 'Laranjinha e cheio de personalidade. Simba vai animar qualquer ambiente com suas travessuras.', 'https://images.unsplash.com/photo-1768523506095-deb25e8f13a3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxvcmFuZ2UlMjB0YWJieSUyMGNhdCUyMGN1cmlvdXMlMjBwb3J0cmFpdHxlbnwxfHx8fDE3NzI2NDc2NjJ8MA&ixlib=rb-4.1.0&q=80&w=1080', 'Popular', 'disponível'),
('Bolt', '6 meses', 'cachorro', 'macho', 'Cheio de energia e amor para dar. Bolt precisa de espaço para brincar e correr.', 'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxodXNreSUyMHB1cHB5JTIwYmx1ZSUyMGV5ZXN8ZW58MXx8fHwxNzI2Mzg5MTI1fDA&ixlib=rb-4.1.0&q=80&w=1080', 'Nova', 'disponível'),
